-- Optional split-service privileges. Apply using an operator connection;
-- no passwords or runtime LOGIN roles are generated by this migration.
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='ark_accounts') THEN
    CREATE ROLE ark_accounts NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='ark_billing') THEN
    CREATE ROLE ark_billing NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS;
  END IF;
END $$;
GRANT USAGE ON SCHEMA ark_kash,neon_auth TO ark_accounts;
GRANT SELECT (id,name,email,"emailVerified",banned) ON neon_auth."user" TO ark_accounts;
GRANT INSERT,SELECT ON ark_kash.accounts TO ark_accounts;
GRANT SELECT (user_id,status,entitled_until) ON ark_kash.purchases TO ark_accounts;
GRANT INSERT,SELECT ON ark_kash.key_envelopes TO ark_accounts;
GRANT USAGE ON SCHEMA ark_kash TO ark_billing;
GRANT INSERT,SELECT,UPDATE ON ark_kash.purchases TO ark_billing;
GRANT INSERT,SELECT ON ark_kash.webhook_events TO ark_billing;
